# Let's create some candidate trigger patterns and test them on clean images
# The patch is 3-5 pixels wide, placed 1 pixel in from one corner

def make_white_square_patch(size=4, corner='top_left'):
    """Create a white square patch at the specified corner, 1 pixel in"""
    patch = torch.zeros(3, 32, 32)
    if corner == 'top_left':
        patch[:, 1:1+size, 1:1+size] = 1.0
    elif corner == 'top_right':
        patch[:, 1:1+size, 32-size-1:32-1] = 1.0
    elif corner == 'bottom_left':
        patch[:, 32-size-1:32-1, 1:1+size] = 1.0
    elif corner == 'bottom_right':
        patch[:, 32-size-1:32-1, 32-size-1:32-1] = 1.0
    return patch

def make_checkerboard_patch(size=4, corner='top_left'):
    """Create a checkerboard patch"""
    patch = torch.zeros(3, 32, 32)
    for c in range(3):
        for i in range(size):
            for j in range(size):
                val = 1.0 if (i + j) % 2 == 0 else 0.0
                if corner == 'top_left':
                    patch[c, 1+i, 1+j] = val
                elif corner == 'top_right':
                    patch[c, 1+i, 32-size-1+j] = val
                elif corner == 'bottom_left':
                    patch[c, 32-size-1+i, 1+j] = val
                elif corner == 'bottom_right':
                    patch[c, 32-size-1+i, 32-size-1+j] = val
    return patch

def make_noise_patch(size=4, corner='top_left'):
    """Create random black/white noise patch"""
    patch = torch.zeros(3, 32, 32)
    noise = (torch.rand(3, size, size) > 0.5).float()
    if corner == 'top_left':
        patch[:, 1:1+size, 1:1+size] = noise
    elif corner == 'top_right':
        patch[:, 1:1+size, 32-size-1:32-1] = noise
    elif corner == 'bottom_left':
        patch[:, 32-size-1:32-1, 1:1+size] = noise
    elif corner == 'bottom_right':
        patch[:, 32-size-1:32-1, 32-size-1:32-1] = noise
    return patch

# Apply patches to clean images and see what the network predicts
corners = ['top_left', 'top_right', 'bottom_left', 'bottom_right']
sizes = [3, 4, 5]
patch_types = ['white', 'checkerboard', 'noise']

# Let's test a few images from each class to see if any trigger causes a consistent misclassification
test_images = x_clean[:100]  # Use first 100 images
test_labels = y_clean[:100]

print("Testing trigger candidates...")
for size in sizes:
    for corner in corners:
        for patch_type in patch_types:
            if patch_type == 'white':
                patch = make_white_square_patch(size, corner)
            elif patch_type == 'checkerboard':
                patch = make_checkerboard_patch(size, corner)
            else:
                patch = make_noise_patch(size, corner)

            # Apply patch to test images (need to denormalize, add patch, renormalize)
            # The images are uint8 [0,255], normalized in forward()
            # We need to add the patch in pixel space before normalization

            # Convert to float [0,1], add patch, then convert back to uint8
            imgs_float = test_images.float() / 255.0
            # Patch is in [0,1] range
            patched = torch.clamp(imgs_float + patch.unsqueeze(0), 0, 1)
            patched_uint8 = (patched * 255).to(torch.uint8)

            logits = forward(W, patched_uint8)
            preds = logits.argmax(dim=1)

            # Check if predictions are heavily biased to one class
            pred_counts = torch.bincount(preds, minlength=10)
            max_class = pred_counts.argmax().item()
            max_count = pred_counts[max_class].item()

            if max_count > 50:  # If more than 50% go to one class
                print(f"  Size={size}, Corner={corner}, Type={patch_type}: Class {max_class} ({max_count}/100)")

print("Done testing")
